package com.ecommerce.backend.service;
import com.ecommerce.backend.entity.*;
import com.ecommerce.backend.repository.*;
import com.ecommerce.backend.exception.*;
import java.util.*;
import java.time.*;
import java.math.BigDecimal;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @ActiveProfiles("test") @Transactional @AutoConfigureMockMvc
class AdminModulesIntegrationTest {
 @Autowired AdminOperationsService ops;@Autowired AdminContentService content;@Autowired AdminTechnicalService tech;
 @Autowired ResenaProductoService publicReviews;@Autowired PedidoRepository orders;@Autowired JdbcTemplate jdbc;@Autowired AyudaService help;@Autowired MockMvc mvc;
 UUID actor=UUID.randomUUID();
 Pedido order(String status){return orders.saveAndFlush(Pedido.builder().numeroPedido("ADM-"+UUID.randomUUID().toString().substring(0,20)).usuarioId(UUID.randomUUID()).estado(status).subtotal(BigDecimal.TEN).total(BigDecimal.TEN).tipoDocumento("DNI").numeroDocumento("12345678").nombreCompleto("Cliente módulo").email("test@example.test").telefono("999999999").direccionEnvio("Dirección de prueba").build());}
 UUID product(){UUID id=UUID.randomUUID(),cat=UUID.randomUUID(),type=UUID.randomUUID();jdbc.update("INSERT INTO rya.categorias(id,nombre,slug) VALUES (?,?,?)",cat,"Prueba",cat.toString());jdbc.update("INSERT INTO rya.tipos_producto(id,codigo) VALUES (?,?)",type,"T"+type.toString().substring(0,7));jdbc.update("INSERT INTO rya.productos(id,categoria_id,tipo_id,sku,nombre,slug,precio_base) VALUES (?,?,?,?,?,?,?)",id,cat,type,id.toString(),"Producto de prueba",id.toString(),10);return id;}
 @Test void cancelaSoloPendientesSinIntentosYRegistraMotivo(){var pending=order("PENDIENTE_PAGO");ops.cancel(pending.getId(),"Cancelado a petición del cliente",actor);assertEquals("CANCELADO",jdbc.queryForObject("SELECT estado FROM rya.pedidos WHERE id=?",String.class,pending.getId()));assertEquals(1,((List<?>)ops.order(pending.getId()).get("historial")).size());var paid=order("PAGADO");assertThrows(BadRequestException.class,()->ops.cancel(paid.getId(),"No debe cancelarse",actor));var uncertain=order("PENDIENTE_PAGO");jdbc.update("INSERT INTO rya.pagos(id,pedido_id,pasarela,monto,moneda,estado) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),uncertain.getId(),"MERCADO_PAGO",10,"PEN","processing");assertThrows(BadRequestException.class,()->ops.cancel(uncertain.getId(),"No duplicar el cobro",actor));}
 @Test void moderaSinAlterarAutorTextoYPideVersion(){UUID p=product(),user=UUID.randomUUID(),id=UUID.randomUUID();jdbc.update("INSERT INTO rya.usuarios(id,nombre,email) VALUES (?,?,?)",user,"Autora original",user+"@example.test");jdbc.update("INSERT INTO rya.resenas_producto(id,usuario_id,producto_id,calificacion,comentario,publicada) VALUES (?,?,?,?,?,?)",id,user,p,5,"Texto original de reseña",false);ops.moderate(id,"APROBADA","Opinión revisada",0,actor);assertTrue(jdbc.queryForObject("SELECT publicada FROM rya.resenas_producto WHERE id=?",Boolean.class,id));assertEquals("Texto original de reseña",jdbc.queryForObject("SELECT comentario FROM rya.resenas_producto WHERE id=?",String.class,id));assertThrows(ConflictException.class,()->ops.moderate(id,"OCULTA","Versión antigua",0,actor));assertEquals(1L,ops.reviews("APROBADA",0).get("total"));assertEquals("Autora original",publicReviews.listarPublicadas(p).getResenas().getFirst().getAutor());ops.moderate(id,"OCULTA","Contenido oculto tras revisión",1,actor);assertEquals(0,publicReviews.listarPublicadas(p).getTotal());}
 @Test void publicaFAQContenidoYContactoConControlDeVersion(){UUID id=content.save(null,"FAQ","¿Cómo retirar?","Presenta tu documento en el horario publicado.","inicio",null,0,true,"","",0,actor);assertTrue(help.preguntas("retirar",null,0,20).content().stream().anyMatch(row->row.id().equals(id)));content.save(id,"FAQ","¿Cómo retirar?","Ahora requiere confirmación previa.","inicio",null,0,false,"","",0,actor);assertFalse(help.preguntas("retirar",null,0,20).content().stream().anyMatch(row->row.id().equals(id)));assertThrows(ConflictException.class,()->content.save(id,"FAQ","Viejo","Contenido anterior","inicio",null,0,true,"","",0,actor));content.save(null,"BANNER","Título editorial","Contenido publicado","inicio",null,0,true,"https://example.com","",0,actor);content.save(null,"BANNER","Borrador","No publicado","inicio",null,0,false,"","",0,actor);assertEquals(1,content.published("inicio").size());assertTrue(content.published("experiencias").isEmpty());assertThrows(BadRequestException.class,()->content.save(null,"BANNER","Mal enlace","No publicar","inicio",null,0,true,"javascript:alert(1)","",0,actor));content.contact("help@example.test","123456789","51999999999","L-V 9 a 18",0,actor);assertEquals("help@example.test",content.contact().get("email"));}
 @Test void postventaTieneEtapasYNoModificaPagoNiStock(){var paid=order("PAGADO");UUID id=ops.createCase(paid.getNumeroPedido(),"GARANTIA","El cliente reporta una falla","https://example.com/evidencia",actor);assertThrows(BadRequestException.class,()->ops.resolve(id,"CERRADA","No se deben saltar etapas",0,actor));ops.resolve(id,"EN_REVISION","Revisión de evidencia recibida",0,actor);assertThrows(ConflictException.class,()->ops.resolve(id,"APROBADA","Versión desactualizada del caso",0,actor));ops.resolve(id,"APROBADA","Se autoriza gestionar la garantía",1,actor);ops.resolve(id,"CERRADA","Atención de garantía completada",2,actor);assertEquals("PAGADO",jdbc.queryForObject("SELECT estado FROM rya.pedidos WHERE id=?",String.class,paid.getId()));assertEquals(1L,ops.cases(0).get("total"));}
 @Test void reportesUsanSoloVentasPagadasYRangoValido(){var paid=order("PAGADO");order("PENDIENTE_PAGO");var today=LocalDate.now(ZoneId.of("America/Lima"));var report=ops.reports(today.minusDays(1),today.plusDays(1));assertEquals(0,BigDecimal.TEN.compareTo((BigDecimal)report.get("totalVentas")));assertThrows(BadRequestException.class,()->ops.reports(today,today.minusDays(1)));assertThrows(BadRequestException.class,()->ops.reports(today.minusYears(2),today));}
 @Test void agrupaVentasPorDiaDePeru(){var paid=order("PAGADO");jdbc.update("UPDATE rya.pedidos SET created_at=? WHERE id=?",OffsetDateTime.parse("2026-10-21T03:00:00Z"),paid.getId());var result=ops.reports(LocalDate.parse("2026-10-20"),LocalDate.parse("2026-10-20"));var daily=(java.util.List<?>)result.get("ventas");assertEquals(1,daily.size());assertEquals("2026-10-20",((java.util.Map<?,?>)daily.getFirst()).get("fecha"));}
 @Test void compatibilidadExigeFuenteBiosCorrectaYVersion(){UUID cpu=product(),board=product(),source=UUID.randomUUID(),revision=UUID.randomUUID(),bios=UUID.randomUUID();jdbc.update("INSERT INTO rya.fuentes_tecnicas(id,titulo,url) VALUES (?,?,?)",source,"Fuente de prueba","https://example.com/support");jdbc.update("INSERT INTO rya.especificaciones_cpu(producto_id,modelo,socket,familia,generacion,nucleos,hilos,potencia_base_w,tiene_graficos_integrados,fuente_id,verificada_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)",cpu,"CPU prueba","AM4","Ryzen","5000",6,12,65,false,source,OffsetDateTime.now());jdbc.update("INSERT INTO rya.revisiones_placa(id,producto_id,modelo,revision,socket,chipset,fuente_id,verificada_at) VALUES (?,?,?,?,?,?,?,?)",revision,board,"Placa prueba","1.0","AM4","B550",source,OffsetDateTime.now());jdbc.update("INSERT INTO rya.versiones_bios(id,placa_revision_id,version,orden,fuente_id) VALUES (?,?,?,?,?)",bios,revision,"1001",1,source);assertThrows(BadRequestException.class,()->tech.save(cpu,revision,bios,source,"SOPORTADO","Soporte revisado en fabricante",null,false,actor));tech.save(cpu,revision,bios,source,"SOPORTADO","Soporte revisado en fabricante",null,true,actor);assertEquals(1L,tech.list(0).get("total"));assertThrows(ConflictException.class,()->tech.save(cpu,revision,bios,source,"NO_SOPORTADO","Edición de una versión antigua",null,true,actor));}
 @Test void rutasAdministrativasRechazanUsuariosYValidanSolicitudes()throws Exception{for(String path:List.of("/api/v1/admin/operacion/pedidos","/api/v1/admin/operacion/resenas","/api/v1/admin/contenido","/api/v1/admin/tecnica/compatibilidad","/api/v1/admin/operacion/reportes")){mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).with(jwt())).andExpect(status().isForbidden());}mvc.perform(post("/api/v1/admin/operacion/postventa").with(jwt().jwt(t->t.subject(actor.toString()).claim("app_metadata",Map.of("role","admin")))).contentType("application/json").content("{}")).andExpect(status().isBadRequest());}
}
